DEFAULT_VALUES = {'Age': 46.0, 'Number of Dependents': 0.0, 'Zip Code': 93518.0, 'Latitude': 36.205465, 'Longitude': -119.595293, 'Number of Referrals': 0.0, 'Tenure in Months': 29.0, 'Avg Monthly Long Distance Charges': 25.69, 'Avg Monthly GB Download': 21.0, 'Monthly Charge': 70.05, 'Total Charges': 1394.55, 'Total Refunds': 0.0, 'Total Extra Data Charges': 0.0, 'Total Long Distance Charges': 401.44, 'Total Revenue': 2108.64, 'Gender': 'Male', 'Married': 'No', 'City': 'Los Angeles', 'Offer': 'Offer B', 'Phone Service': 'Yes', 'Multiple Lines': 'No', 'Internet Service': 'Yes', 'Internet Type': 'Fiber Optic', 'Online Security': 'No', 'Online Backup': 'No', 'Device Protection Plan': 'No', 'Premium Tech Support': 'No', 'Streaming TV': 'No', 'Streaming Movies': 'No', 'Streaming Music': 'No', 'Unlimited Data': 'Yes', 'Contract': 'Month-to-Month', 'Paperless Billing': 'Yes', 'Payment Method': 'Bank Withdrawal'}
CATEGORICAL_COLUMNS = list(CATEGORY_MAPS.keys())

def load_sample_data():
    with open(DATA_PATH, "r", encoding="utf-8") as file:
        payload = json.load(file)
    if not isinstance(payload, dict) or not isinstance(payload.get("data"), list):
        raise ValueError('data.json harus berisi objek dengan key "data" berupa list.')
    return payload["data"]

def prepare_model_input(records):
    if isinstance(records, dict):
        records = [records]
    if not isinstance(records, list) or not records:
        raise ValueError('"data" harus berupa satu objek pelanggan atau list pelanggan yang tidak kosong.')
    frame = pd.DataFrame(records)
    missing = [column for column in MODEL_COLUMNS if column not in frame.columns]
    if missing:
        raise ValueError("Kolom input belum lengkap: " + ", ".join(missing))
    frame = frame[MODEL_COLUMNS].copy()
    for column in MODEL_COLUMNS:
        if column in CATEGORICAL_COLUMNS:
            mapping = CATEGORY_MAPS[column]
            frame[column] = frame[column].where(frame[column].notna(), DEFAULT_VALUES[column]).astype(str)
            unknown = sorted(set(frame[column]) - set(mapping))
            if unknown:
                raise ValueError(f"Kategori tidak dikenal untuk kolom {column}: {unknown}")
            frame[column] = frame[column].map(mapping)
        else:
            frame[column] = pd.to_numeric(frame[column], errors="coerce")
            frame[column] = frame[column].fillna(DEFAULT_VALUES[column])
    if frame.isnull().any().any():
        raise ValueError("Input masih memiliki nilai kosong yang tidak dapat diproses.")
    return frame

@app.route("/", methods=["GET"])
def home():
    return jsonify({
        "message": "API prediksi Telecom Customer Churn aktif.",
        "endpoints": {
            "GET /sample-data": "Menampilkan 5 data pelanggan dari data.json.",
            "POST /predict": "Prediksi churn untuk satu atau beberapa pelanggan."
        }
    })

@app.route("/sample-data", methods=["GET"])
def sample_data():
    try:
        return jsonify({"data": load_sample_data()[:5]})
    except (OSError, ValueError) as error:
        return jsonify({"error": str(error)}), 400

@app.route("/predict", methods=["POST"])
def predict():
    body = request.get_json(silent=True)
    if not isinstance(body, dict) or "data" not in body:
        return jsonify({"error": 'Kirim JSON dengan format {"data": {...}} atau {"data": [{...}, {...}]}.'}), 400
    try:
        input_frame = prepare_model_input(body["data"])
        predictions = joblib_model.predict(input_frame)
        probabilities = joblib_model.predict_proba(input_frame) if hasattr(joblib_model, "predict_proba") else None
        results = []
        classes = list(getattr(joblib_model, "classes_", []))
        churn_index = classes.index(1) if 1 in classes else None
        for i, prediction in enumerate(predictions):
            result = {"prediction": int(prediction), "customer_status": "Churned" if int(prediction) == 1 else "Stayed"}
            if probabilities is not None and churn_index is not None:
                result["churn_probability"] = round(float(probabilities[i][churn_index]), 4)
            results.append(result)
        return jsonify({"results": results})
    except ValueError as error:
        return jsonify({"error": str(error)}), 400
    except Exception:
        app.logger.exception("Gagal melakukan prediksi")
        return jsonify({"error": "Terjadi kesalahan saat memproses prediksi."}), 500

